import { useEffect, useState } from "react";
import api from "../api";

function Members() {
  const [families, setFamilies] = useState([]);
  const [familyName, setFamilyName] = useState("");

  const [form, setForm] = useState({
    name: "",
    age: "",
    goal: "Weight Loss",
    health_condition: "None",
    diet: "Vegetarian"
  });

  const loadFamilies = async () => {
    const res = await api.get("/families/");
    setFamilies(res.data);
  };

  useEffect(() => {
    loadFamilies();
  }, []);

  const addFamily = async () => {
    await api.post("/families/", {
      name: familyName
    });

    setFamilyName("");
    loadFamilies();
  };

  const addMember = async (familyId) => {
    await api.post(`/families/${familyId}/members`, {
      name: form.name,
      age: parseInt(form.age),
      goal: form.goal,
      health_condition: form.health_condition,
      diet: form.diet
    });

    setForm({
      name: "",
      age: "",
      goal: "Weight Loss",
      health_condition: "None",
      diet: "Vegetarian"
    });

    loadFamilies();
  };

  return (
    <div>
      <h1>Family Members</h1>

      <div className="card">
        <h3>Create Family</h3>

        <input
          placeholder="Family Name"
          value={familyName}
          onChange={(e) =>
            setFamilyName(e.target.value)
          }
        />

        <button onClick={addFamily}>
          Add Family
        </button>
      </div>

      {families.map((family) => (
        <div className="card" key={family.id}>
          <h2>{family.name}</h2>

          <h3>Add Member</h3>

          <input
            placeholder="Name"
            value={form.name}
            onChange={(e) =>
              setForm({ ...form, name: e.target.value })
            }
          />

          <input
            placeholder="Age"
            value={form.age}
            onChange={(e) =>
              setForm({ ...form, age: e.target.value })
            }
          />

          <select
            value={form.goal}
            onChange={(e) =>
              setForm({ ...form, goal: e.target.value })
            }
          >
            <option>Weight Loss</option>
            <option>Weight Gain</option>
            <option>Maintain Weight</option>
            <option>Muscle Gain</option>
            <option>Diabetic Control</option>
          </select>

          <select
            value={form.health_condition}
            onChange={(e) =>
              setForm({
                ...form,
                health_condition: e.target.value
              })
            }
          >
            <option>None</option>
            <option>Diabetes</option>
            <option>BP</option>
            <option>Thyroid</option>
            <option>Heart Disease</option>
            <option>PCOS</option>
          </select>

          <select
            value={form.diet}
            onChange={(e) =>
              setForm({ ...form, diet: e.target.value })
            }
          >
            <option>Vegetarian</option>
            <option>Non Vegetarian</option>
            <option>Vegan</option>
            <option>Eggetarian</option>
          </select>

          <button
            onClick={() =>
              addMember(family.id)
            }
          >
            Add Member
          </button>

          <hr />

          <h3>Registered Members</h3>

          {family.members &&
          family.members.length > 0 ? (
            family.members.map((m) => (
              <div
                key={m.id}
                style={{
                  padding: "10px",
                  marginBottom: "10px",
                  background: "#1e293b",
                  borderRadius: "10px"
                }}
              >
                <strong>{m.name}</strong> ({m.age})<br />
                Goal: {m.goal}<br />
                Condition: {m.health_condition}<br />
                Diet: {m.diet}
              </div>
            ))
          ) : (
            <p>No members added yet.</p>
          )}
        </div>
      ))}
    </div>
  );
}

export default Members;
